const nw = msg.data.new_state;
const ow = msg.data.old_state;
if (!nw || !ow || !nw.attributes.wpisy) return null;

// 1. Pobieramy dane z sensora PLANU LEKCJI (zakładając, że slug jest ten sam)
const studentSlug = nw.entity_id.replace('sensor.vultron_freq_', '');
const planEntity = global.get('homeassistant').homeAssistant.states['sensor.vultron_plan_' + studentSlug];
const lekcjeZPlanu = (planEntity && planEntity.attributes.lekcje) ? planEntity.attributes.lekcje : [];

const noweWpisy = nw.attributes.wpisy;
const stareWpisy = ow.attributes.wpisy || [];
const imie = nw.attributes.friendly_name ? nw.attributes.friendly_name.split(': ')[1] : "Uczeń";

const catMap = { 2: "Nieobecność ❌", 4: "Spóźnienie ⚠️", 7: "Zwolnienie 🚪" };

let noweAlerty = noweWpisy.filter(n => {
    if (![2, 4, 7].includes(n.k)) return false;
    return !stareWpisy.some(o => o.d === n.d && o.t === n.t && o.k === n.k);
});

if (noweAlerty.length > 0) {
    let msgList = noweAlerty.map(a => {
        // 2. Szukamy przedmiotu w planie lekcji (pasująca data i godzina rozpoczęcia)
        const lekcja = lekcjeZPlanu.find(l => l.d === a.d && l.g.startsWith(a.t));
        const przedmiot = lekcja ? lekcja.p : "Nieznany przedmiot";

        return `- **${catMap[a.k]}**\n   📖 ${przedmiot}\n   📅 ${a.d} o godz. ${a.t}`;
    });

    msg.payload = {
        title: `Alert frekwencji: ${imie}`,
        message: `Zarejestrowano nowe zdarzenia:\n${msgList.join('\n\n')}`,
        notification_id: "vultron_freq_alert"
    };
    return msg;
}
return null;
